import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createHash } from 'node:crypto';
const [root, output] = process.argv.slice(2);
const paths = ['openclaw_runtime/src/context-engine/prompt-contribution-authority.ts', 'openclaw_runtime/src/plugins/hook-before-agent-start.types.ts'];
const hashes = () => Object.fromEntries(paths.map(path => [path, createHash('sha256').update(readFileSync(resolve(root, path))).digest('hex')]));
const before = hashes();
const authority = await import(pathToFileURL(resolve(root, paths[0])).href);
const { PLUGIN_PROMPT_MUTATION_AUTHORITIES: fields } = await import(pathToFileURL(resolve(root, paths[1])).href);
const events = [];
function attempt(source, scope, requiredAuthority, declaration, shouldDeny, stage) {
  const request = { source, scope, requiredAuthority, declaration: declaration ?? null };
  events.push({ index: events.length, type: 'request', stage, request });
  try {
    const status = authority.admitPromptContribution(source, scope, requiredAuthority, { mode: 'enforce', declaration });
    assert.equal(shouldDeny, false, 'An unauthorized contribution was admitted');
    events.push({ index: events.length, type: 'decision', stage, allowed: true, status });
  } catch (error) {
    assert.equal(shouldDeny, true, 'An authorized contribution was denied');
    assert.equal(error.code, 'PROMPT_CONTRIBUTION_AUTHORITY_DENIED');
    events.push({ index: events.length, type: 'decision', stage, allowed: false,
      error: { name: error.name, code: error.code, source: error.source, scope: error.scope, requiredAuthority: error.requiredAuthority, reason: error.reason } });
  }
}
for (const [scope, requiredAuthority] of Object.entries(fields)) {
  attempt('trace-plugin', scope, requiredAuthority, undefined, requiredAuthority !== 'append_data', 'undeclared');
  const declaration = { source: 'trace-plugin', scope: [scope], authority: [requiredAuthority], reason: 'Recorded fixture producer registration' };
  attempt('trace-plugin', scope, requiredAuthority, declaration, false, 'continuation-with-registration');
}
for (const source of ['dcs-knowledge', 'context-block:knowledge', 'compass-ssp', 'session-start:summary', 'memory-inject-pilot:runtime-memory']) {
  const declaration = authority.getBuiltinPromptContributionDeclaration(source);
  assert.ok(declaration);
  attempt(source, 'message_replacement', 'replace_messages', declaration, true, 'core-escalation');
  attempt(source, declaration.scope[0], declaration.authority[0], declaration, false, 'continuation-with-fixed-core-scope');
}
const after = hashes();
assert.deepEqual(after, before, 'Source changed during trace recording');
const report = { schema: 'PromptAuthorityBehavioralTrace/v1', driven_by: 'agent', actor: 'codex/prompt-authority', generatedAt: new Date().toISOString(),
  scope: 'Actual authority module calls; deterministic API fixture, not provider/runtime effects', sourceStable: true, sourceHashes: before,
  fieldCount: Object.keys(fields).length, deniedDecisionCount: events.filter(event => event.type === 'decision' && !event.allowed).length,
  admittedUnauthorizedCount: 0, events };
writeFileSync(output, JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify({ fieldCount: report.fieldCount, deniedDecisionCount: report.deniedDecisionCount, admittedUnauthorizedCount: report.admittedUnauthorizedCount }));
